values.content:
=You are a research analyst grading article relevance.

MONITORING TOPIC: "{{ $('Set Config').item.json.topic }}"

ARTICLE:
Title: {{ $json.title }}
URL: {{ $json.url }}
Snippet: {{ $json.content }}

TASK: Decide if this article is directly relevant to the monitoring topic.
An article is relevant if it:
- Contains new information or developments about the topic
- Is substantive (not just a passing mention)
- Adds value to a market research digest

Respond ONLY with JSON in this exact format:
{"relevance": "relevant" or "not_relevant", "score": 0.0-1.0, "reason": "one sentence"}

parameters.jsCode:
// Parse the LLM's JSON response safely
const raw = $input.item.json.message?.content || '{}';
let parsed = {};
try {
  // Strip markdown fences if present
  const cleaned = raw.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch(e) {
  parsed = { relevance: 'not_relevant', score: 0, reason: 'parse error' };
}

return {
  ...($('Split Articles').item.json),
  relevance: parsed.relevance,
  relevance_score: parsed.score,
  relevance_reason: parsed.reason,
  topic: $('Set Config').item.json.topic,
  runId: $('Set Config').item.json.runId
};

const matches = $json.matches || [];
const DEDUP_THRESHOLD = 0.95;
const isDuplicate = matches.length > 0 && matches[0].score >= DEDUP_THRESHOLD;

return {
  ...($('Parse Grade').item.json),
  embedding: $('Embed Article (for dedup)').item.json.embedding,
  is_duplicate: isDuplicate,
  dedup_score: matches.length > 0 ? matches[0].score : 0
};

// Parse insights array from LLM
const raw = $json.message?.content || '[]';
let insights = [];
try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  insights = JSON.parse(cleaned);
  if (!Array.isArray(insights)) insights = [String(insights)];
} catch(e) {
  insights = ['Could not parse insights for: ' + $('Evaluate Duplicate').item.json.title];
}

return {
  ...($('Evaluate Duplicate').item.json),
  insights: insights,
  insights_text: insights.map(i => '• ' + i).join('\n')
};

values.content:
=You are writing an executive summary for a daily market research digest.

TOPIC: "{{ $('Set Config').first().json.topic }}"
DATE: {{ $now.format('YYYY-MM-DD') }}

ARTICLES PROCESSED:
{{ $json.data.map(a => a.title + '\n' + a.insights_text).join('\n\n') }}

Write a 2-3 sentence executive summary that captures the most important developments across all articles today. Be specific, factual, and concise. Focus on patterns and the most impactful findings.

parameters.jsCode:
const articles = $('Aggregate All Articles').first().json.data || [];
const execSummary = $json.message?.content || 'No summary generated.';
const topic = $('Set Config').first().json.topic;
const runDate = $now.format('YYYY-MM-DD');

// Build Notion-ready markdown sections
const articleSections = articles.map(a => {
  const bullets = a.insights_text || '• No insights extracted.';
  return `### [${a.title}](${a.url})
*Relevance score: ${(a.relevance_score || 0).toFixed(2)}*

${bullets}`;
}).join('

---

');

const fullDigest = `# 📰 Market Research Digest: ${topic}
**Date:** ${runDate}

---

## 🔍 Executive Summary

${execSummary}

---

## 📄 Articles & Insights

${articleSections}

---
*Generated by AI Market Research Monitor · ${$now.toISO()} UTC*`;

return {
  topic,
  runDate,
  articleCount: articles.length,
  execSummary,
  fullDigest,
  topHeadline: articles.length > 0 ? articles[0].title : 'No articles found',
  topInsight: articles.length > 0 ? articles[0].insights?.[0] : 'N/A'
};

